const payOrderStats = `-- name: PayOrderStats :one
SELECT COUNT(*) AS cnt, COALESCE(SUM(CASE WHEN status = 1 THEN money ELSE 0 END), 0) AS money,
  COALESCE(SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END), 0) AS pending,
  COALESCE(SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END), 0) AS paid
FROM pay_orders WHERE created_at >= ?
`

type PayOrderStatsRow struct {
	Cnt     int64
	Money   interface{}
	Pending interface{}
	Paid    interface{}
}

func (q *Queries) PayOrderStats(ctx context.Context, createdAt int64) (PayOrderStatsRow, error) {
	row := q.db.QueryRowContext(ctx, payOrderStats, createdAt)
	var i PayOrderStatsRow
	err := row.Scan(
		&i.Cnt,
		&i.Money,
		&i.Pending,
		&i.Paid,
	)
	return i, err
}

